/// Raven `EntIsGlass`.
///
/// Source: `oracle/oracle/codemp/game/NPC_combat.c:1114-1124`
pub fn EntIsGlass(check: *mut gentity_t) -> qboolean {
    unsafe {
        if !(*check).classname.is_null()
            && Q_stricmp(c"func_breakable".as_ptr(), (*check).classname as *const c_char) == 0
            && (*check).count == 1
            && (*check).health <= 100
        {
            return 1;
        }
        0
    }
}

